const $tabelData = $('#tabelData'),
    $formData = $('#formData'),
    $modalDiv = $('#modalDiv'),
    formCek = CirebonwebForm.FormCek($formData);

// --- Pembulatan nilai ---

// Membulatkan ke atas pada kelipatan 500 (123001 -> 123500, 123501 -> 124000)
function bulat500(nilai) {
    return Math.ceil(Number(nilai) / 500) * 500;
}

// Membulatkan maksimal 2 angka di belakang koma (2.032 -> 2.03, 0.279 -> 0.28)
function bulat2(nilai) {
    return Math.round(Number(nilai) * 100) / 100;
}

// Teks rupiah termasuk nilai negatif (mis. sisa kelebihan bayar)
function rupiahTeks(nilai) {
    const angka = Number(nilai) || 0;
    return (angka < 0 ? '-Rp ' : 'Rp ') + CirebonwebFormat.Rupiah(Math.abs(angka));
}

// --- Rumus produk terpilih ---

function rumusProduk() {
    return Number($('#produk_id').find(':selected').data('rumus'));
}

// Menampilkan label rumus dan mengatur tampilan harga minimum
function tampilkanRumus() {
    const $opt = $('#produk_id').find(':selected');
    const rumus = Number($opt.data('rumus'));

    if (!$opt.val()) {
        $('.rumus').text('?');
        $('#rumus').val('null');
    } else if (rumus === 0) {
        $('.rumus').text('0');
        $('#rumus').val('Perkalian Luas');
    } else if (rumus === 1) {
        $('.rumus').text('1');
        $('#rumus').val('Perkalian Qty');
    } else {
        $('.rumus').text('?');
        $('#rumus').val('null');
    }

    // Harga minimum hanya berlaku untuk perkalian luas
    $('#wrapHargaMinimum').toggle(rumus === 0);
}

// Toggle harga minimum selalu mulai dari Tidak; nilainya tidak disimpan di database
function toggleHargaMinimum(aktif) {
    const $toggle = $('#minimum_toggle');

    if (typeof $toggle.bootstrapToggle === 'function') {
        $toggle.bootstrapToggle(aktif ? 'on' : 'off');
    } else {
        $toggle.prop('checked', Boolean(aktif));
    }
}

// --- Kalkulasi luas dan jumlah ---

function hitungJumlah() {
    const rumus = rumusProduk();
    const harga = Number(CirebonwebFormat.unRupiah($('#harga').val())) || 0;
    const qty = Number($('#qty').val()) || 0;
    const lebar = Number(String($('#lebar').val()).replace(',', '.')) || 0;
    const panjang = Number(String($('#panjang').val()).replace(',', '.')) || 0;
    const luas = bulat2(lebar * panjang);

    let jumlah = rumus === 0 ? luas * qty * harga : qty * harga;

    // Pembulatan jumlah ke kelipatan 500
    jumlah = bulat500(jumlah);

    // Harga minimum (khusus perkalian luas) bila toggle diaktifkan
    if (rumus === 0 && $('#minimum_toggle').prop('checked')) {
        jumlah = Math.max(jumlah, harga);
    }

    $('#luas').val(luas.toFixed(2));
    $('#jumlah').val(CirebonwebFormat.Rupiah(jumlah));
}

// --- DataTables rincian nota ---
$(function () {
    $tabelData.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${urlThis}/tabel`,
            type: 'POST',
            data: function (d) { d.nota_id = idNota; }
        },
        autoWidth: false,
        responsive: true,
        searching: false,
        ordering: false,
        dom: 'Blfrtip',
        buttons: [
            { text: 'Add', action: () => { simpan(); } },
            {
                text: 'Reload',
                action: function (e, dt) {
                    Swal.fire({ icon: 'success', title: 'Informasi', text: 'Selesai reload tabel ke kondisi awal', showConfirmButton: false, timer: 1300 })
                        .then(function () { dt.ajax.reload(null, true); });
                }
            },
            { extend: 'excelHtml5', exportOptions: { columns: ':not(.no-export)', orthogonal: 'export' } }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 2, 3], className: 'dt-body-center' },
            { targets: [4, 5], className: 'dt-body-right', render: CirebonwebFormat.RupiahTabel },
            { targets: [10, 11], render: (data) => CirebonwebFormat.Tanggal(data, 'waktu') },
        ]
    });
});

// --- Produk per kategori ---
// tanpaIsiNilai = true dipakai saat edit agar nilai tersimpan tidak ditimpa data produk
function loadProduk(kategori, selectedId, callback, tanpaIsiNilai) {
    const $produk = $('#produk_id');

    $produk.prop('disabled', true).empty().append('<option value="">-- Pilih --</option>');

    if (kategori === '' || kategori === null || typeof kategori === 'undefined') {
        $produk.val('').trigger('change');
        if (callback) callback();
        return;
    }

    $.post(`${urlThis}/loadproduk`, { kategori: kategori }, function (rows) {
        rows.forEach(function (row) {
            $produk.append(`<option value="${row.id}" data-lebar="${row.lebar}" data-panjang="${row.panjang}" data-rumus="${row.rumus}" data-harga="${row.harga}">${row.nama}</option>`);
        });

        $produk.prop('disabled', false).val(selectedId || '');

        if (tanpaIsiNilai) {
            tampilkanRumus();
        } else {
            $produk.trigger('change');
        }

        if (callback) callback();
    });
}

// --- Ringkasan nota diperbarui lewat AJAX, tanpa reload halaman ---
function segarkanRingkasanNota() {
    if (!idNota) return;

    CirebonwebForm.FormFetch(`${notaUrl}/getid`, { id: idNota }, 'POST', {}).done(function (response) {
        if (!response.success) return;

        const d = response.data;
        const status = ['Belum Bayar', 'Belum Lunas', 'Lunas', 'Hapus Nota'];

        $('#ringSubtotal').text(rupiahTeks(d.subtotal));
        $('#ringDiskon').text(rupiahTeks(d.diskon_nominal));
        $('#ringNettotal').text(rupiahTeks(d.nettotal));
        $('#ringBayar').text(rupiahTeks(d.bayar));
        $('#ringSisa').text(rupiahTeks(d.sisa));

        $('#infoStatusNota').text(status[Number(d.status_nota)] || '-');
        $('#infoStatusBarang').text(Number(d.status_barang) === 1 ? 'Sudah Ambil' : 'Belum Ambil');
        $('#infoTglAmbil').text(d.tgl_ambil || '-');
        $('#infoKeterangan').text(d.keterangan || '-');
    });
}

// --- Modal, select2, dan pemicu kalkulasi ---
$(function () {
    $(document).on('select2:open', () => document.querySelector('.select2-container--open .select2-search__field')?.focus());

    $(document).on('change', '#kategori', function () {
        loadProduk($(this).val());
    });

    $(document).on('change', '#produk_id', function () {
        const $opt = $(this).find(':selected');

        tampilkanRumus();

        if (!$opt.val()) {
            $('#harga').val(CirebonwebFormat.Rupiah(0));
            hitungJumlah();
            return;
        }

        $('#lebar').val(CirebonwebFormat.Desimal($opt.data('lebar')) || 0);
        $('#panjang').val(CirebonwebFormat.Desimal($opt.data('panjang')) || 0);
        $('#harga').val(CirebonwebFormat.Rupiah(Number($opt.data('harga')) || 0));

        hitungJumlah();
    });

    $(document).on('input change', '#harga, #qty, #lebar, #panjang', hitungJumlah);
    $(document).on('change', '#minimum_toggle', hitungJumlah);

    $modalDiv.on('shown.bs.modal', function () {
        $modalDiv.find('.select2').each(function () {
            const $select = $(this);
            if ($select.hasClass('select2-hidden-accessible')) {
                $select.select2('destroy');
            }
            $select.select2({ dropdownParent: $modalDiv });
        });
        formCek.resetInitial();
    }).on('hidden.bs.modal', function () {
        CirebonwebForm.FormReset(this);
        $modalDiv.find('.select2.select2-hidden-accessible').select2('destroy');
    });
});

// --- Simpan item rincian nota ---
function simpan(id) {
    const isEdit = id > 0;
    const $modalTitle = $('.modal-title');
    const $btnSubmit = $('#btnSubmit');

    // FormReset mengosongkan input hidden, jadi id nota dipasang ulang setiap kali
    $formData.find('#nota_id').val(idNota);

    if (isEdit) {
        CirebonwebForm.FormFetch(`${urlThis}/getid`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;

            const data = response.data;
            $modalTitle.text('Edit Data');
            $btnSubmit.text('Update');

            // Tampilkan nilai tersimpan apa adanya, tidak dihitung ulang
            $formData.find('#id').val(data.id);
            $formData.find('#kategori').val(data.kategori);
            $formData.find('#finishing_id').val(data.finishing_id || '').trigger('change');
            $formData.find('#tema').val(data.tema);
            $formData.find('#lebar').val(CirebonwebFormat.Desimal(data.lebar));
            $formData.find('#panjang').val(CirebonwebFormat.Desimal(data.panjang));
            $formData.find('#luas').val(CirebonwebFormat.Desimal(data.luas));
            $formData.find('#qty').val(data.qty);
            $formData.find('#harga').val(CirebonwebFormat.Rupiah(data.harga));
            $formData.find('#jumlah').val(CirebonwebFormat.Rupiah(data.jumlah));
            $formData.find('#keterangan').val(data.keterangan);

            // Muat produk tanpa menimpa nilai tersimpan, lalu tetapkan acuan form
            loadProduk(data.kategori, data.produk_id, function () {
                toggleHargaMinimum(false);
                formCek.resetInitial();
                $modalDiv.modal('show');
            }, true);
        });
    } else {
        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        CirebonwebForm.FormReset($modalDiv);
        $formData.find('#kategori').val('').trigger('change');
        $formData.find('#finishing_id').val('').trigger('change');
        toggleHargaMinimum(false);
        $modalDiv.modal('show');
    }

    $formData.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            nota_id: { required: true, digits: true },
            produk_id: { required: true, digits: true },
            tema: { required: true, maxlength: 100 },
            qty: { required: true, digits: true, min: 1 },
            keterangan: { maxlength: 100 }
        },
        submitHandler: function () {
            if (!formCek.isChanged()) return false;

            hitungJumlah();

            const data = $formData.serializeArray();
            data.forEach(function (item) {
                if (['harga', 'jumlah'].includes(item.name)) {
                    item.value = CirebonwebFormat.unRupiah(item.value);
                }
            });

            CirebonwebForm.FormFetch(`${urlThis}/simpan`, data, 'POST', {
                before_call: function () {
                    $btnSubmit.attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () { $btnSubmit.attr('disabled', false).html('Simpan'); }
            }).done(function (response) {
                if (!response.success) return;
                $modalDiv.modal('hide');
                Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                    .then(function () {
                        $tabelData.DataTable().ajax.reload(null, false);
                        segarkanRingkasanNota();
                    });
            });

            return false;
        }
    }));
}

// --- Hapus item rincian nota ---
function hapus(id) {
    Swal.fire({
        title: 'Konfirmasi',
        html: 'Apakah yakin ingin menghapus data ini? <br> Data akan dihapus secara permanen!',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Ya, hapus!'
    }).then(function (result) {
        if (!result.isConfirmed) return;

        CirebonwebForm.FormFetch(`${urlThis}/hapus`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                .then(function () {
                    $tabelData.DataTable().ajax.reload(null, false);
                    segarkanRingkasanNota();
                });
        });
    });
}

// --- Pindahkan item nota dari Draft ke alur produksi ---
function produksi() {
    Swal.fire({
        title: 'Konfirmasi',
        html: 'Item berstatus Draft akan dipindahkan ke alur produksi.<br>Internal berbahan menjadi <b>Antrian</b>, kategori lain menjadi <b>Proses</b>.',
        icon: 'question',
        showCancelButton: true,
        confirmButtonText: 'Ya, lanjutkan!'
    }).then(function (result) {
        if (!result.isConfirmed) return;

        CirebonwebForm.FormFetch(`${urlThis}/produksi`, { nota_id: idNota }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                .then(function () {
                    $tabelData.DataTable().ajax.reload(null, false);
                    $('#btnProduksi').prop('disabled', true).find('.badge').remove();
                });
        });
    });
}
